import{bQ as t,aL as o,u as r,G as s}from"./chunks/framework.BT-C7ti3.js";const a=JSON.parse('{"title":"Cogito, ergo sum","description":"人生是旷野，我思故我在。","frontmatter":{"title":"Cogito, ergo sum","filename":260629,"tags":["杂谈"],"date":"2026-06-29T00:00:00.000Z","description":"人生是旷野，我思故我在。","references":[{"title":"分数线出来那天，我看见了三个中国 - 烟火，《浮世散章》","url":"https://mp.weixin.qq.com/s/wa1vpGidCK5x_PonxgYQqw"}],"top":false,"share":true,"delete":false,"head":[["link",{"rel":"canonical","href":"https://coderama.top/posts/2026/260629"}]]},"headers":[],"relativePath":"posts/2026/260629.md","filePath":"posts/2026/260629.md","lastUpdated":1783175776000}');const n=t({name:"posts/2026/260629.md"},[["render",function(t,a,n,u,q,e){return o(),r("div",null,[...a[0]||(a[0]=[s('<h1 id="分数线出来那天-我看见了三个中国" tabindex="-1">分数线出来那天，我看见了三个中国 <a class="header-anchor" href="#分数线出来那天-我看见了三个中国" aria-label="Permalink to &quot;分数线出来那天，我看见了三个中国&quot;">​</a></h1><p>6月24号晚上，我刷着手机，看各个省份的分数线一条一条跳出来。<br> 江苏、浙江、山东、河北、河南……每一个数字出来，都有几十万家庭在同一瞬间屏住了呼吸。<br> 我突然想，如果有一个上帝视角，能把这一刻的中国切成三个横截面，他会看到什么？<br> 不是东中西部，不是一二三线，而是<strong>三个截然不同的中国，在同一时刻，被同一根分数线，划开了。</strong></p><hr><h2 id="——第一个中国-是准备好的中国。" tabindex="-1">——第一个中国，是准备好的中国。 <a class="header-anchor" href="#——第一个中国-是准备好的中国。" aria-label="Permalink to &quot;——第一个中国，是准备好的中国。&quot;">​</a></h2><p>这里的父母，在孩子还上小学的时候，就已经想清楚了：高考不是一场赌博，是一场长达十二年的排兵布阵。<br> 他们给孩子报的培训班，不是&quot;补差班&quot;，是&quot;培优班&quot;。他们选的学区房，不是&quot;有学上就行&quot;，是&quot;这个学校的清北率是多少&quot;。他们给孩子定的目标，不是&quot;考个大学&quot;，是&quot;考哪个大学&quot;。<br> 分数线出来的那天，这些家庭的反应，不是惊喜，是<strong>确认</strong>。<br> &quot;嗯，正常发挥。&quot;&quot;这个分数，可以冲一下复旦。&quot;&quot;比预估低了8分，但也在接受范围内。&quot;<br> 你看，他们的语气里没有侥幸，没有&quot;老天保佑&quot;，因为<strong>这件事从一开始就不是靠运气。</strong><br> 这是一个<strong>有底气的中国</strong>。底气的来源不是钱——虽然钱确实很重要——而是一种叫做&quot;规划&quot;的东西。这些父母在自己的人生里，早已经学会了怎么把一个大目标拆成十二年，然后一年一年去兑现。<br> 他们不是不焦虑，他们是把焦虑提前消化了。等到分数线出来的那天，他们只需要做一道数学题：<strong>这个分数，配哪所学校。</strong><br> 这不是公平与否的问题，这是一个事实：<strong>有些孩子，从出生那一刻起，就在一条被精心设计过的跑道上。</strong></p><hr><h2 id="——第二个中国-是赌上去的中国。" tabindex="-1">——第二个中国，是赌上去的中国。 <a class="header-anchor" href="#——第二个中国-是赌上去的中国。" aria-label="Permalink to &quot;——第二个中国，是赌上去的中国。&quot;">​</a></h2><p>这里的父母，没有那么长远的规划，但他们有一个非常坚定的信念：<strong>&quot;我这一辈子就这样了，孩子必须考上大学。&quot;</strong><br> 这个信念背后，是一整套牺牲逻辑：省吃俭用报补习班，放弃自己的社交去陪读，在孩子面前永远念叨一句话：&quot;你只要好好学习，别的都不用管。&quot;<br> 分数线出来的那天，这些家庭的反应，是<strong>过山车</strong>。<br> 考上了，全家喜极而泣，好像十二年的苦都没白吃。没考上，天塌了，父母的第一反应不是&quot;孩子难不难受&quot;，而是&quot;我这么多年的付出怎么算&quot;。<br> 这个中国里，高考不是一场考试，是<strong>一场家庭命运的豪赌</strong>。赌注是全家人十二年的生活质量，赌赢了的奖励是&quot;阶层不下滑&quot;，赌输了的代价是&quot;我这辈子白干了&quot;。<br> 你看，这个中国的底色是<strong>恐惧</strong>。<br> 恐惧的是什么？不是孩子考不上，是 <strong>&quot;我这么努力地想让你赢，你居然让我输了&quot;。</strong><br> 这句话从来不说出口，但它藏在每一个陪读妈妈的疲惫里，藏在每一个父亲在工地上多扛两袋水泥的沉默里。<br> 这个中国里，最让人心疼的不是孩子，是父母。他们把全部的希望都押在这一场考试上，却没有想过一个问题：<strong>如果孩子考上了，然后呢？如果孩子没考上，然后呢？</strong><br> &quot;然后&quot;这两个字，他们不敢想。因为一想，就会发现：<strong>原来十二年里，他们只教会了孩子一件事——考试。</strong></p><hr><h2 id="——第三个中国-是沈默的中国。" tabindex="-1">——第三个中国，是沈默的中国。 <a class="header-anchor" href="#——第三个中国-是沈默的中国。" aria-label="Permalink to &quot;——第三个中国，是沈默的中国。&quot;">​</a></h2><p>这里的父母，也想让孩子考大学。但他们说这句话的时候，语气是怯生生的，好像在许一个不太敢许的愿。<br> 他们不是不爱孩子，是他们自己也没想明白：上大学这件事，到底意味着什么。<br> 分数线出来的那天，这些家庭的反应，是<strong>沉默</strong>。<br> 不是因为考得太差，也不是因为考得特别好。是因为<strong>这个分数，无论高低，都好像没有改变命运的力量。</strong><br> 你可能会说：&quot;怎么会？考上985、211，不就改变命运了吗？&quot;<br> 你说得对。但你知道在第三个中国里，考上一个好大学意味着什么吗？<br><strong>意味着孩子要离开家，去一个完全陌生的城市，学一个完全不懂的专业，然后发现自己和同学在见识、眼界、谈吐上的差距，不是努力就能追上的。</strong><br> 这个差距，不是智商，不是勤奋，是<strong>从出生开始就累积的文化资本</strong>。<br> 第一个中国的孩子，从小去博物馆、看话剧、和父母讨论新闻；第三个中国的孩子，从小到大最远可能只去过县城，父母能教给他的，只有&quot;好好读书&quot;四个字。<br> 所以你看，<strong>分数线划开的不是分数，是起跑线。</strong><br> 而那些在起跑线上就已经落后了十八年的人，你告诉他&quot;加油，你可以的&quot;，这句话的残忍程度，不亚于<em>对着一个没有腿的人说&quot;跑起来&quot;</em>。</p><hr><p>我写这三个中国，不是为了制造对立，也不是为了让你觉得&quot;原来我这么幸运&quot;或者&quot;原来我这么失败&quot;。<br> 我是想说一件事：<strong>一根分数线，划不开公平，它只能划开真相。</strong><br> 真相就是：<strong>这场考试，从设计之初，就不是为了公平，而是为了筛选。</strong><br> 筛选什么？筛选那些有能力、有资源、有耐力的人，把他们送进更好的大学，然后让他们在更好的大学里，获得更好的人脉、更好的机会、更好的未来。<br> 这不是黑暗，这是<strong>现实</strong>。<br> 但现实不等于正当。<br> 正当的问题是：<strong>一个国家的未来，到底应该由一场考试来分配，还是应该由一个人的能力、创造力、和他对社会的贡献来分配？</strong><br> 这个问题，分数线回答不了。它只能回答：&quot;你考了多少分，能上什么学校。&quot;<br> 但&quot;能上什么学校&quot;和&quot;能成为什么样的人&quot;，中间隔着一整个太平洋。</p><hr><p><em>我有一个朋友</em>，高考发挥失常，比预估低了将近100分。<br> 他爸看完分数，沉默了很久，然后说了一句话：&quot;要不，复读？&quot;<br> 他说：&quot;不用。我想明白了，我不是一个考试型选手。但我可能是一个做事型的人。&quot;<br> 他爸说：&quot;做事也要有文凭啊。&quot;<br> 他说：&quot;文凭是敲门砖。但门敲开了之后，拼的不是文凭。&quot;<br> 后来他没复读，去了一所普通本科。大学四年，他没把时间花在刷GPA上，而是去了一家创业公司实习，从打杂做起，做到了项目主管。<br> 毕业那年，他拿着这份实习经历，加上自己在大学里做过的几个小项目，拿到了一家互联网公司的offer。起薪不算高，但他学到了学校里永远教不会的东西：<strong>怎么在不确定的环境里做事。</strong><br> 今年，他的年薪已经超过了那些当年考上了985的同学。<br> 我不是在鼓吹&quot;读书无用论&quot;。<br> 我是在说：<em><strong>分数线出来之后，你的人生才刚刚开始。而这场人生，考核方式不是一张卷子，而是一系列的：你怎么面对失败？你怎么做出选择？你怎么在没有人逼你学习的时候，还能自己往前走？</strong></em><br> 这些能力，高考不考。但人生每天都在考。</p><hr><p>写到这里，可能有人会说：&quot;你这是在安慰那些考砸了的人。但现实就是，985就是比211好，211就是比双非好。你安慰有什么用？&quot;<br> 我说：<strong>安慰不是目的，清醒才是。</strong><br> 清醒地认识到：</p><ul><li>如果你考得好，那恭喜你，你赢得了一个更好的平台。<strong>但平台不是终点，你还得自己走。</strong></li><li>如果你考得不好，那也没关系，你只是输掉了一场考试，<strong>不是输掉了人生</strong>。</li><li>如果你是孩子家长，请记住：<strong>你对孩子最重要的责任，不是让他考上大学，是让他成为一个无论考没考上，都能活得下去、活得像样的人。</strong><br> 这三句话，每一句虽不感性，不煽动，但都是我花了很长时间才想明白的事。</li></ul><hr><p>分数线出来的那天，我看见了三个中国。<br> 第一个中国在规划，第二个中国在赌博，第三个中国在沉默。<br> 但在这三个中国之外，我还看见了第四个东西——<br><strong>是那些无论考好考坏，都能在查分夜的第二天，照常醒来、照常生活的人。</strong><br> 他们可能是第一个中国的，也可能是第二个或第三个。<br> 他们的共同点只有一个：<strong>他们没有被一根分数线定义。</strong><br> 这根线，划得开学校，划不开人生。划得开起点，划不开终点。划得开十二年的埋头苦读，但划不开一个人面对未来时，眼里的光。</p><hr><p>最后，我想对今天查分的你说一句话：<br> 无论你考了多少分，无论你是不是如愿以偿——<br><em><strong>这根分数线，是你人生中第一道被公开标注的&quot;分水岭&quot;。但绝对不是最后一道。</strong></em><br> 在你以后的日子里，你还会遇到无数根&quot;分数线&quot;：——求职时的学历门槛——升职时的论资排辈——买房时的首付红线——结婚时的房车标准……<br> 每一根线，都在试图告诉你：&quot;你到这里就够了&quot;或者&quot;你还差一点&quot;。<br> 但你要记住：<em><strong>所有的线，都是别人画的。唯一的底气，来自于你心里那根线——你知道自己在哪里，要去哪里。</strong></em><br> 这根线，高考不教，分数线不管。<br> 但它，才是你真正的&quot;录取通知书&quot;。</p><p><a class="img-fancybox" href="https://s1.imagehub.cc/images/2026/06/29/978aa43ada46ada7d34b53971999dedf.png" data-fancybox="gallery" data-caption="我要读书"><img class="post-img" src="https://s1.imagehub.cc/images/2026/06/29/978aa43ada46ada7d34b53971999dedf.png" alt="我要读书" loading="lazy"><span class="post-img-tip">我要读书</span></a></p>',23)])])}]]);export{a as __pageData,n as default};
